def separate_paren_groups(paren_string: str) -> List[str]:
    groups = []
    cur_group = ''
    stack = []
    for char in paren_string:
        if char == '(':
            stack.append(char)
            cur_group += char
        elif char == ')':
            stack.pop()
            if not stack:
                groups.append(cur_group)
                cur_group = ''
            else:
                cur_group += char
    if cur_group:
        groups.append(cur_group)
    return groups
