def verify_isbn(isbn: str) -> str:
    if len(isbn) != 13:
        return isbn

    checksum = 0
    for i in range(12):
        if isbn[i].isdigit():
            checksum += (len(isbn) - i - 1) * int(isbn[i])

    checksum = (11 - checksum % 11) % 11
    if checksum == 10:
        checksum = "X"
    else:
        checksum = str(checksum)

    if checksum == isbn[-1]:
        return "Right"
    else:
        return isbn[:-1] + checksum

